"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[899],{51003:e=>{e.exports=JSON.parse('{"functions":[{"name":"setupBackgroundSounds","desc":"Creates and starts every `BACKGROUND_SOUNDS` entry. Guarded by\\n`runningBackgroundSounds`, so only the first call does anything.\\n\\nPer entry: applies `looped` and `volume`, instantiates each nested effect\\nfrom the `effects` table (`effectType` is used as a ClassName and its\\nproperties are assigned verbatim), then starts playback \u2014 deferring to\\n`Sound.Loaded` when the asset is not resident yet, since `TimeLength` is\\nneeded for the `randomStartTime` and `synced` offsets.\\n\\nEntries naming a sound that is not in the `Sounds` data table warn and are\\nskipped.\\n\\nCalled by `LoadingScreen.run()` before the bootstrapper runs, and again by\\n[SoundController.init].","params":[],"returns":[],"function_type":"static","source":{"line":118,"path":"src/Client/Features/Core/Controllers/SoundController.luau"}},{"name":"setMusicTrack","desc":"Crossfades the background music to the given looped track. Fades the\\ncurrent track out and the new track in via TweenService on Sound.Volume.\\nNo-ops if the requested track is already active.","params":[{"name":"soundId","desc":"","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":183,"path":"src/Client/Features/Core/Controllers/SoundController.luau"}},{"name":"setMusicVolume","desc":"Sets the background music volume (0\u20131) immediately. Cancels an in-flight\\nfade-in so the tween can\'t finish at a stale target afterwards.","params":[{"name":"volume","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":225,"path":"src/Client/Features/Core/Controllers/SoundController.luau"}},{"name":"init","desc":"Bootstrap hook. Creates one `Sound` under `SoundService` for every\\non-demand entry in the `Sounds` data table, then calls\\n[SoundController.setupBackgroundSounds] if the loading screen has not\\nalready done so.","params":[],"returns":[],"function_type":"static","source":{"line":260,"path":"src/Client/Features/Core/Controllers/SoundController.luau"}}],"properties":[],"types":[],"name":"SoundController","desc":"Materializes every entry in `Core.Assets.CoreSounds` as a `Sound`\\ninstance parented to `SoundService`, so the rest of the client can play a\\nsound by name without ever creating instances.\\n\\nTwo categories:\\n\\n* **Background** \u2014 the `BACKGROUND_SOUNDS` table in this file. Each entry\\n  is configured (looped, volume, nested effect instances, randomized or\\n  server-synced start time) and auto-played once its asset loads. Today\\n  that is just `desert-ambience-loop`.\\n* **On-demand** \u2014 everything else in `Sounds`. Created bare and left\\n  stopped for `PlaySFX` to trigger by name.\\n\\n:::note\\n[SoundController.setupBackgroundSounds] is called twice on a normal boot \u2014\\nonce by `LoadingScreen.run()` so the ambience is audible during the load,\\nand again from [SoundController.init] once the bootstrapper reaches this\\ncontroller. The `runningBackgroundSounds` guard makes the second call a\\nno-op. That also means `LoadingScreen` requires this module directly rather\\nthan going through the controller container.\\n:::\\n\\nThere is no cleanup path \u2014 sounds are created once and live for the\\nsession.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Client"],"source":{"line":33,"path":"src/Client/Features/Core/Controllers/SoundController.luau"}}')}}]);